### 2. 파일 생성 및 구현

#### 2.1 [모델 및 테스트]
```javascript
// model.mjs
export class TaskModel {
  constructor(storageKey = 'focus-board-v1') {
    this.storageKey = storageKey;
    this.tasks = [];
    this.statusMessage = '';
  }

  load() {
    const rawData = localStorage.getItem(this.storageKey);
    if (!rawData) {
      this.tasks = [];
      return true;
    }
    try {
      const parsed = JSON.parse(rawData);
      if (!Array.isArray(parsed)) throw new Error('Invalid format');
      this.tasks = parsed;
      return true;
    } catch (e) {
      this.statusMessage = '데이터를 불러오는 중 오류가 발생하여 목록을 초기화했습니다.';
      this.tasks = [];
      return false;
    }
  }

  save() {
    localStorage.setItem(this.storageKey, JSON.stringify(this.tasks));
  }

  validateTask(title, subject, minutes) {
    const trimmedTitle = title.trim();
    const trimmedSubject = subject.trim();
    const minVal = parseInt(minutes, 10);

    if (!trimmedTitle || trimmedTitle.length > 100) return { error: '제목은 1~100자 사이여야 합니다.', field: 'title' };
    if (!trimmedSubject || trimmedSubject.length > 30) return { error: '과목은 1~30자 사이여야 합니다.', field: 'subject' };
    if (isNaN(minVal) || minVal < 1 || minVal > 480) return { error: '학습 시간은 1~480분 사이여야 합니다.', field: 'minutes' };

    return { title: trimmedTitle, subject: trimmedSubject, minutes: minVal };
  }

  addTask(title, subject, minutes) {
    const validated = this.validateTask(title, subject, minutes);
    if (validated.error) return validated;

    const newTask = {
      id: Date.now().toString(),
      title: validated.title,
      subject: validated.subject,
      minutes: validated.minutes,
      completed: false,
      createdAt: new Date().toISOString()
    };
    this.tasks.push(newTask);
    this.save();
    return newTask;
  }

  toggleTask(id) {
    const task = this.tasks.find(t => t.id === id);
    if (task) {
      task.completed = !task.completed;
      this.save();
    }
  }

  deleteTask(id) {
    this.tasks = this.tasks.filter(t => t.id !== id);
    this.save();
  }

  getStats() {
    return {
      total: this.tasks.length,
      active: this.tasks.filter(t => !t.completed).length,
      completed: this.tasks.filter(t => t.completed).length,
      totalMinutes: this.tasks.reduce((acc, t) => acc + t.minutes, 0)
    };
  }

  getFilteredTasks(filter, search) {
    let list = this.tasks;
    if (filter === 'active') list = list.filter(t => !t.completed);
    if (filter === 'completed') list = list.filter(t => t.completed);

    if (search) {
      const q = search.toLowerCase();
      list = list.filter(t => t.title.toLowerCase().includes(q) || t.subject.toLowerCase().includes(q));
    }
    return list;
  }
}
```

```javascript
// model.test.mjs
import test from 'node:test';
import assert from 'node:assert';
import { TaskModel } from './model.mjs';

// Mock localStorage for Node environment
global.localStorage = {
  store: {},
  getItem(key) { return this.store[key] || null; },
  setItem(key, value) { this.store[key] = value.toString(); }
};

test('Task Validation Logic', () => {
  const model = new TaskModel();

  // Valid input
  assert.strictEqual(model.validateTask(' 공부하기 ', ' 수학 ', '60').title, '공부하기');

  // Invalid inputs
  assert.ok(model.validateTask('', '수학', '60').error);
  assert.ok(model.validateTask('a'.repeat(101), '수학', '60').error);
  assert.ok(model.validateTask('제목', '과목', '500').error);
});

test('Task Operations & Stats', () => {
  const model = new TaskModel('test-key');
  model.tasks = []; // Reset

  model.addTask('Task 1', 'Math', '30');
  model.addTask('Task 2', 'Science', '60');

  assert.strictEqual(model.tasks.length, 2);
  assert.strictEqual(model.getStats().totalMinutes, 90);

  const taskId = model.tasks[0].id;
  model.toggleTask(taskId);
  assert.strictEqual(model.getStats().completed, 1);

  model.deleteTask(taskId);
  assert.strictEqual(model.tasks.length, 1);
});

test('Filter & Search', () => {
  const model = new TaskModel('test-key');
  model.tasks = [
    { id: '1', title: 'Reading', subject: 'English', completed: false, minutes: 10 },
    { id: '2', title: 'Coding', subject: 'JS', completed: true, minutes: 20 }
  ];

  assert.strictEqual(model.getFilteredTasks('active').length, 1);
  assert.strictEqual(model.getFilteredTasks('all', 'read').length, 1);
  assert.strictEqual(model.getFilteredTasks('all', 'NONE').length, 0);
});
